import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, float, smoothstep, uniform, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, Vector3, DoubleSide, FrontSide, LinearSRGBColorSpace, SRGBColorSpace } = ctx.THREE;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10'
  };
  const ink = new Color(colors.ink);
  const paper = new Color(colors.paper);
  const accent = new Color(colors.accent);
  const surface = new Color(colors.surface);

  const tl = gsap.timeline({ paused: true });

  // ---- Backdrop: vertical gradient surface -> ink ----
  const bgMat = new MeshBasicNodeMaterial({
    side: DoubleSide,
    toneMapped: false
  });
  bgMat.colorNode = mix(
    uniform(surface),
    uniform(ink),
    smoothstep(float(0.0), float(1.0), uv().y.mul(-1).add(1))
  );
  const bgGeo = new PlaneGeometry(8.5, 7.2);
  const bgMesh = new Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  group.add(bgMesh);

  // ---- Contact shadow plane ----
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.5,
    side: DoubleSide,
    toneMapped: false
  });
  const shadowUvR = uv().sub(0.5).length();
  shadowMat.colorNode = uniform(new Color(0x000000));
  shadowMat.opacityNode = float(0.55).mul(smoothstep(float(0.5), float(0.05), shadowUvR));
  const shadowGeo = new PlaneGeometry(2.6, 2.0);
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -1.55, -0.02);
  shadowMesh.rotation.x = -0.05;
  group.add(shadowMesh);

  // ---- Card plane (card backing with subtle gradient) ----
  const cardMat = new MeshBasicNodeMaterial({
    side: DoubleSide,
    toneMapped: true
  });
  // Card has a dark machined gradient: surface base with subtle top-lift
  cardMat.colorNode = mix(
    uniform(new Color(0x050508)),
    uniform(new Color(0x111118)),
    smoothstep(float(0.0), float(1.0), uv().y)
  );
  const cardGeo = new PlaneGeometry(3.6, 2.8, 1, 1);
  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, 0.0);
  cardMesh.userData.baseY = 0;
  group.add(cardMesh);

  // ---- Image texture plane (feature-card.png) overlaid on card ----
  const imageMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: FrontSide,
    toneMapped: true
  });
  const imageGeo = new PlaneGeometry(3.4, 2.1);
  const imageMesh = new Mesh(imageGeo, imageMat);
  imageMesh.position.set(0, 0.22, 0.01);
  group.add(imageMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      imageMat.map = tex;
      imageMat.needsUpdate = true;
    });
  }

  // ---- Accent edge (thin red strip at bottom of card) ----
  const accentMat = new MeshBasicNodeMaterial({
    side: DoubleSide,
    toneMapped: false
  });
  accentMat.colorNode = uniform(accent);
  const accentGeo = new PlaneGeometry(3.4, 0.04);
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(0, -1.25, 0.02);
  group.add(accentMesh);

  // ---- Top-left accent corner mark ----
  const cornerMat = new MeshBasicNodeMaterial({ side: DoubleSide, toneMapped: false });
  cornerMat.colorNode = uniform(accent);
  const cornerH = new Mesh(new PlaneGeometry(0.5, 0.02), cornerMat);
  cornerH.position.set(-1.55, 1.28, 0.03);
  group.add(cornerH);
  const cornerV = new Mesh(new PlaneGeometry(0.02, 0.5), cornerV ? cornerV.material : cornerMat);
  cornerV.position.set(-1.55, 1.05, 0.03);
  group.add(cornerV);

  // ---- Quote text (Lora serif display) ----
  const quoteText = 'The precision of each timepiece redefined what I expect from craftsmanship.';
  const quoteMesh = ctx.fontAtlas.createText(quoteText, {
    fontSize: 62,
    color: colors.paper,
    align: 'center',
    maxWidthPx: 480
  });
  quoteMesh.position.set(0, -0.45, 0.04);
  group.add(quoteMesh);

  // ---- Attribution text (JetBrains Mono caption) ----
  const attribText = 'MARCO REYES   /   COLLECTOR, GENEVA';
  const attribMesh = ctx.fontAtlas.createText(attribText, {
    fontSize: 34,
    color: colors.accent,
    align: 'center',
    letterSpacingPx: 3
  });
  attribMesh.position.set(0, -0.92, 0.04);
  group.add(attribMesh);

  // ---- Open quotation mark glyph (large serif accent) ----
  const openMark = ctx.fontAtlas.createText('"', {
    fontSize: 120,
    color: colors.accent,
    align: 'left'
  });
  openMark.position.set(-1.45, 0.55, 0.03);
  group.add(openMark);

  // ---- Entrance animation (rise-in) ----
  group.position.y += 0.4;
  group.scale.set(1, 1, 1);
  gsap.to(group.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out'
  });
  gsap.from(group.scale, {
    x: 0.96, y: 0.96, z: 0.96,
    duration: 0.9,
    ease: 'power4.out'
  });

  // ---- Apply cinematic primitives ----
  const primitiveCleanups = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    if (prim.name && ctx.primitives[prim.name]) {
      const result = ctx.primitives[prim.name](group, prim.params ?? {});
      if (result && result.cleanup) primitiveCleanups.push(result.cleanup);
    }
  }

  // ---- Interactions ----
  let hoverActive = false;
  let hoverTl = null;

  group.userData.handlers = {
    onPointerEnter: () => {
      hoverActive = true;
      hoverTl = gsap.timeline();
      hoverTl.to(cardMesh.position, {
        y: cardMesh.userData.baseY + 0.15,
        duration: 0.4,
        ease: 'power2.out'
      }, 0);
      hoverTl.to(accentMesh.scale, {
        x: 1.08,
        duration: 0.35,
        ease: 'power2.out'
      }, 0);
      hoverTl.to(openMark.position, {
        y: 0.65,
        duration: 0.4,
        ease: 'power2.out'
      }, 0);
    },
    onPointerLeave: () => {
      hoverActive = false;
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(cardMesh.position, {
        y: cardMesh.userData.baseY,
        duration: 0.3,
        ease: 'power2.inOut'
      }, 0);
      hoverTl.to(accentMesh.scale, {
        x: 1.0,
        duration: 0.3,
        ease: 'power2.inOut'
      }, 0);
      hoverTl.to(openMark.position, {
        y: 0.55,
        duration: 0.3,
        ease: 'power2.inOut'
      }, 0);
    },
    onPointerDown: () => {
      gsap.to(group.scale, {
        x: 0.97, y: 0.97, z: 0.97,
        duration: 0.12,
        ease: 'power2.out',
        onComplete: () => {
          gsap.to(group.scale, {
            x: 1, y: 1, z: 1,
            duration: 0.3,
            ease: 'power4.out'
          });
        }
      });
    },
    onClick: () => {
      ctx.emit('hub-pricing.select', { source: 'quote-panel' });
    }
  };

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    tl.kill();
    for (const c of primitiveCleanups) {
      try { c(); } catch (e) { /* noop */ }
    }
    bgGeo.dispose(); bgMat.dispose();
    cardGeo.dispose(); cardMat.dispose();
    imageGeo.dispose(); imageMat.dispose();
    shadowGeo.dispose(); shadowMat.dispose();
    accentGeo.dispose(); accentMat.dispose();
    cornerH.geometry.dispose(); cornerV.geometry.dispose();
    cornerMat.dispose();
    quoteMesh.parent?.remove(quoteMesh);
    attribMesh.parent?.remove(attribMesh);
    openMark.parent?.remove(openMark);
  };

  return group;
}
